{"exercises": [{"id": "py-list-01", "bloom": "L1", "topic": "listas: indexación", "statement": "Escribe una función ultimo(xs) que devuelva el último elemento de una lista no vacía.", "lang": "python", "tests": ["ultimo([1, 2, 3]) == 3", "ultimo(['a']) == 'a'", "ultimo([None, 0]) == 0"], "expected": "any", "hints": ["Python admite índices negativos", "xs[-1] apunta al último elemento"]}, {"id": "py-list-02", "bloom": "L2", "topic": "bucles for: acumuladores", "statement": "Escribe una función suma_pares(xs) que devuelva la suma de los números pares de la lista. Si no hay pares, devuelve 0.", "lang": "python", "tests": ["suma_pares([1, 2, 3, 4]) == 6", "suma_pares([1, 3, 5]) == 0", "suma_pares([]) == 0", "suma_pares([-2, -4, 7]) == -6"], "expected": "int", "hints": ["inicializa un acumulador en 0", "usa n % 2 == 0 para detectar pares"]}, {"id": "py-list-03", "bloom": "L3", "topic": "listas: invertir sin reversed", "statement": "Escribe una función invertir(xs) que devuelva una nueva lista con los elementos en orden inverso, sin usar reversed(), list.reverse() ni slicing [::-1].", "lang": "python", "tests": ["invertir([1, 2, 3]) == [3, 2, 1]", "invertir([]) == []", "invertir(['x']) == ['x']", "(lambda l: (invertir(l), l)[1])([1, 2]) == [1, 2]"], "expected": "list", "hints": ["recorre los índices desde len(xs) - 1 hasta 0", "no modifiques la lista original"]}, {"id": "py-list-04", "bloom": "L3", "topic": "bucles while", "statement": "Escribe una función cuenta_digitos(n) que, usando un bucle while, devuelva cuántos dígitos tiene un entero no negativo n. Considera que 0 tiene 1 dígito.", "lang": "python", "tests": ["cuenta_digitos(0) == 1", "cuenta_digitos(7) == 1", "cuenta_digitos(12345) == 5", "cuenta_digitos(1000) == 4"], "expected": "int", "hints": ["divide entre 10 con // en cada iteración", "trata el caso n == 0 aparte"]}, {"id": "py-list-05", "bloom": "L3", "topic": "listas por comprensión", "statement": "Escribe una función cuadrados_impares(xs) que devuelva, en una sola lista por comprensión, los cuadrados de los números impares de xs, manteniendo el orden.", "lang": "python", "tests": ["cuadrados_impares([1, 2, 3]) == [1, 9]", "cuadrados_impares([2, 4]) == []", "cuadrados_impares([-3, 5]) == [9, 25]"], "expected": "list[int]", "hints": ["la sintaxis es [expr for x in xs if condición]", "en Python, -3 % 2 == 1"]}, {"id": "py-list-06", "bloom": "L4", "topic": "eliminar duplicados preservando orden", "statement": "Escribe una función sin_duplicados(xs) que devuelva una lista con los elementos de xs sin repeticiones, conservando el orden de su primera aparición.", "lang": "python", "tests": ["sin_duplicados([3, 1, 3, 2, 1]) == [3, 1, 2]", "sin_duplicados([]) == []", "sin_duplicados(['a', 'b', 'a']) == ['a', 'b']"], "expected": "list", "hints": ["set() pierde el orden si lo usas directamente", "usa un conjunto auxiliar de vistos"]}, {"id": "py-list-07", "bloom": "L4", "topic": "bucles anidados: matrices", "statement": "Escribe una función transponer(m) que reciba una matriz rectangular como lista de listas y devuelva su transpuesta usando bucles anidados.", "lang": "python", "tests": ["transponer([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]", "transponer([[1]]) == [[1]]", "transponer([[1, 2]]) == [[1], [2]]"], "expected": "list[list]", "hints": ["la nueva matriz tiene len(m[0]) filas", "el elemento m[i][j] pasa a la posición [j][i]"]}, {"id": "py-list-08", "bloom": "L3", "topic": "enumerate y búsqueda", "statement": "Escribe una función indices_de(xs, valor) que devuelva una lista con todas las posiciones en las que aparece valor dentro de xs.", "lang": "python", "tests": ["indices_de([1, 2, 1, 3, 1], 1) == [0, 2, 4]", "indices_de([1, 2], 9) == []", "indices_de([], 0) == []"], "expected": "list[int]", "hints": ["enumerate(xs) te da índice y valor a la vez"]}, {"id": "py-list-09", "bloom": "L4", "topic": "ventanas deslizantes", "statement": "Escribe una función max_suma_ventana(xs, k) que devuelva la suma máxima de k elementos consecutivos de xs. Supón que 1 <= k <= len(xs). Intenta una solución O(n).", "lang": "python", "tests": ["max_suma_ventana([1, 3, -1, 5, 2], 2) == 7", "max_suma_ventana([4], 1) == 4", "max_suma_ventana([-5, -2, -8], 2) == -7", "max_suma_ventana([1, 2, 3], 3) == 6"], "expected": "int", "hints": ["calcula la suma de la primera ventana", "al avanzar, suma el elemento que entra y resta el que sale", "no inicialices el máximo en 0: puede haber negativos"]}, {"id": "py-list-10", "bloom": "L5", "topic": "depuración de bucles", "statement": "El siguiente código pretende eliminar los números negativos de una lista, pero falla con entradas como [-1, -2, 3]:

def quitar_negativos(xs):
